def box_filter(a, k):
    """Separable mean filter via cumulative sums (edge-padded)."""
    def box1d(x, ax):
        c = np.cumsum(np.pad(x, ((1, 1), (0, 0)) if ax == 0 else ((0, 0), (1, 1)),
                             mode='edge'), axis=ax)
        sl_hi = [slice(None)] * x.ndim
        sl_lo = [slice(None)] * x.ndim
        if ax == 0:
            sl_hi[0] = slice(2 * k + 1, None)
            sl_lo[0] = slice(0, x.shape[0])
        else:
            sl_hi[1] = slice(2 * k + 1, None)
            sl_lo[1] = slice(0, x.shape[1])
        return (c[tuple(sl_hi)] - c[tuple(sl_lo)]) / (2 * k + 1)
    return box1d(box1d(a, 0), 1)


