def make_move(board, move):
    """Apply a UCI move (first 4 chars used) to the board in place."""
    fcol = ord(move[0]) - ord("a")
    frow = 8 - int(move[1])
    tcol = ord(move[2]) - ord("a")
    trow = 8 - int(move[3])
    board[trow][tcol] = board[frow][fcol]
    board[frow][fcol] = None


def perft(fen, depth):
    """Count leaf nodes at the given depth (pseudo-legal move tree)."""
    if depth == 0:
        return 1
    board, white_to_move = parse_fen(fen)
    total = 0
    for move in legal_moves(fen):
        make_move(board, move)
        next_fen = _board_to_fen(board, not white_to_move)
        total += perft(next_fen, depth - 1)
        # undo
        fcol = ord(move[0]) - ord("a")
        frow = 8 - int(move[1])
        tcol = ord(move[2]) - ord("a")
        trow = 8 - int(move[3])
        board[frow][fcol] = board[trow][tcol]
        board[trow][tcol] = None
    return total


def _board_to_fen(board, white_to_move):
    rows = []
    for row in board:
        out = []
        empty = 0
        for cell in row:
            if cell is None:
                empty += 1
            else:
                if empty:
                    out.append(str(empty))
                    empty = 0
                out.append(cell)
        if empty:
            out.append(str(empty))
        rows.append("".join(out))
    return "/".join(rows) + " " + ("w" if white_to_move else "b") + " - - 0 1"

