def _attacked(board, row, col, by_white):
    """True if square (row, col) is attacked by the given side."""
    pawn = "P" if by_white else "p"
    knight = "N" if by_white else "n"
    king = "K" if by_white else "k"
    bishop, rook = ("B", "Q") if by_white else ("b", "q")
    rook_p, queen_p = rook if isinstance(rook, tuple) else (rook, rook)
    pawn_row = row + 1 if by_white else row - 1
    if 0 <= pawn_row < 8:
        for dcol in (-1, 1):
            c = col + dcol
            if 0 <= c < 8 and board[pawn_row][c] == pawn:
                return True
    for drow, dcol in KNIGHT_DIRS:
        r, c = row + drow, col + dcol
        if 0 <= r < 8 and 0 <= c < 8 and board[r][c] == knight:
            return True
    for drow, dcol in KING_DIRS:
        r, c = row + drow, col + dcol
        if 0 <= r < 8 and 0 <= c < 8 and board[r][c] == king:
            return True
    for drow, dcol in BISHOP_DIRS:
        r, c = row + drow, col + dcol
        while 0 <= r < 8 and 0 <= c < 8:
            p = board[r][c]
            if p is not None:
                if p == bishop or p == queen_p:
                    return True
                break
            r, c = r + drow, c + dcol
    for drow, dcol in ROOK_DIRS:
        r, c = row + drow, col + dcol
        while 0 <= r < 8 and 0 <= c < 8:
            p = board[r][c]
            if p is not None:
                if p == rook_p or p == queen_p:
                    return True
                break
            r, c = r + drow, c + dcol
    return False


def _castling_moves(board, white_to_move, castling, moves):
    row = 7 if white_to_move else 0
    king = "K" if white_to_move else "k"
    rook = "R" if white_to_move else "r"
    kside = "K" if white_to_move else "k"
    qside = "Q" if white_to_move else "q"
    if board[row][4] != king:
        return
    origin = sq_name(row, 4)
    if kside in castling and board[row][7] == rook:
        path = [(row, 5), (row, 6)]
        if all(board[r][c] is None for r, c in path):
            if not any(_attacked(board, r, c, not white_to_move)
                       for r, c in [(row, 4), (row, 5), (row, 6)]):
                moves.append(origin + sq_name(row, 6))
    if qside in castling and board[row][0] == rook:
        path = [(row, 1), (row, 2), (row, 3)]
        if all(board[r][c] is None for r, c in path):
            if not any(_attacked(board, r, c, not white_to_move)
                       for r, c in [(row, 4), (row, 3), (row, 2)]):
                moves.append(origin + sq_name(row, 2))


CORNER_RIGHTS = {(7, 7): "K", (7, 0): "Q", (0, 7): "k", (0, 0): "q"}


def _updated_castling(castling, move):
    f = (8 - int(move[1]), ord(move[0]) - ord("a"))
    t = (8 - int(move[3]), ord(move[2]) - ord("a"))
    lost = set()
    if f in ((7, 4), (0, 4)):
        lost.update("KQ" if f == (7, 4) else "kq")
    if f in CORNER_RIGHTS:
        lost.add(CORNER_RIGHTS[f])
    if t in CORNER_RIGHTS:
        lost.add(CORNER_RIGHTS[t])
    remaining = "".join(c for c in castling if c not in lost)
    return remaining or "-"


