def _ep_square_after(move):
    """En passant target square string after a move, or '-'."""
    fcol, frow = ord(move[0]) - ord("a"), 8 - int(move[1])
    tcol, trow = ord(move[2]) - ord("a"), 8 - int(move[3])
    if fcol == tcol and abs(trow - frow) == 2:
        return move[0] + str(8 - (frow + trow) // 2)
    return "-"


